SELECT COUNT(DISTINCT customer_id) AS n_customers,
  COUNT(DISTINCT order_id) AS n_orders
FROM sales_lines;

WITH daily AS (
  SELECT account, txn_date, SUM(amount) AS net
  FROM bank_txns GROUP BY account, txn_date
),
acct AS (
  SELECT account, SUM(net) AS total_net FROM daily GROUP BY account
),
ranked AS (
  SELECT account, total_net,
    RANK() OVER (ORDER BY total_net DESC) AS rnk
  FROM acct
)
SELECT account, total_net FROM ranked WHERE rnk <= 2 ORDER BY rnk;

SELECT shipment_id, origin, destination
FROM shipments
WHERE origin IN (
  SELECT origin FROM shipments GROUP BY origin HAVING COUNT(*) >= 4
)
ORDER BY shipment_id;
